    id: "eng-2010-hl-q5-b-iii", topicId: "eng-2-10", conceptId: "identify-use-submerged-arc-welding-saw",
    section: "A", questionRef: "2010 HL Q5(b)(iii)",
    questionText: "Identify one use for submerged arc welding (SAW);",
    tariffModel: {"kind":"fixed"}, totalMarks: 6,
