    schemeCitation: "Marking points quoted from the SEC marking scheme, Engineering 2010 Higher Level — © State Examinations Commission.",
    id: "eng-2010-hl-q7-a-v", topicId: "eng-3-12", conceptId: "distinguish-between-clearance-fit-interference-fit",
    section: "A", questionRef: "2010 HL Q7(a)(v)",
    questionText: "Distinguish between a clearance fit and an interference fit.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 6,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Clearance fit is when the shaft is made smaller than the part it fits into, there is a space to allow the parts to fit together easily.", marks: null },
    { id: "r-2", kind: "point", verbatim: "Interference fit when the shaft is larger than the part it is intended to fit. The parts will have to be forced together.", marks: null },
    ],
