    id: "eng-2010-hl-q7-c-i", topicId: "eng-2-11", conceptId: "magnetic-chuck-or-term-cnc",
    section: "A", questionRef: "2010 HL Q7(c)(i)",
    questionText: "Explain the term CNC.",
