    year: 2012, level: "higher",
    paperFileid: "LC027ALP000EV",
    schemeCitation: "Marking points quoted from the SEC marking scheme, Engineering 2012 Higher Level — © State Examinations Commission.",
    id: "eng-2012-hl-q7-a-iii", topicId: "eng-3-12", conceptId: "term-tolerance-engineering-measurement-systems",
    section: "A", questionRef: "2012 HL Q7(a)(iii)",
    questionText: "Explain the term tolerance in engineering measurement systems;",
    tariffModel: {"kind":"fixed"}, totalMarks: 6,
    rows: [
    { id: "r-1", kind: "point", verbatim: "A tolerance is the extent by which a dimension is allowed to deviate from the nominal or basic size. If a nominal size of an object is 20.00mm with a tolerance of 0.15 then the upper limit is 20.15mm and the lower limit is 19.85mm.", marks: 6 },
    ],
