    id: "eng-2013-hl-q5-a-i", topicId: "eng-2-10", conceptId: "hazards-associated-use-manual-metal-arc",
    section: "A", questionRef: "2013 HL Q5(a)(i)",
    questionText: "Describe three hazards associated with the use of manual metal arc welding in a school engineering room.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 6,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Electric shock due to high voltages. Ensure that equipment is well maintained with cables secured and insulated properly to prevent electric shock.", marks: null },
    { id: "r-2", kind: "point", verbatim: "Fumes created by heating metals. Materials to be welded need to be cleaned and degreased to minimise fumes while welding. Appropriate ventilation systems should be in place.", marks: null },
    { id: "r-3", kind: "point", verbatim: "Hot metals. Protective clothing should be worn including leather gloves, apron, etc.", marks: null },
    { id: "r-4", kind: "point", verbatim: "Intense light. A good quality welding shield with darkened face plates must be worn to protect the user.", marks: null },
    { id: "r-5", kind: "point", verbatim: "Protect others. Appropriate welding curtain or cubicle will ensure that others are not exposed to the UV light emitted from the welding process.", marks: null },
    ],
