    id: "eng-2018-hl-q7-b-ii", topicId: "eng-2-11", conceptId: "reason-balancing-grinding-wheel",
    section: "A", questionRef: "2018 HL Q7(b)(ii)",
    questionText: "Outline one reason for balancing a grinding wheel.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 6,
    rows: [
    { id: "r-1", kind: "point", verbatim: "If a grinding wheel is out of balance the spindle will vibrate and a poor surface finish will result. This has consequences for machine safety.", marks: null },
    { id: "r-2", kind: "point", verbatim: "A wheel is placed on a balancing stand and weights are moved around the flange to balance the wheel. This is similar to balancing a car wheel.", marks: null },
    ],
