    schemeCitation: "Marking points quoted from the SEC marking scheme, Engineering 2018 Higher Level — © State Examinations Commission.",
    id: "eng-2018-hl-q8-c-i", topicId: "eng-2-15", conceptId: "aid-diagram-suitable-steering-mechanism-golf",
    section: "A", questionRef: "2018 HL Q8(c)(i)",
