    id: "eng-2019-hl-q6-a-ii", topicId: "eng-1-9", conceptId: "suitable-manufacturing-process-mass-production-oarlock",
    section: "A", questionRef: "2019 HL Q6(a)(ii)",
    questionText: "Name and describe a suitable manufacturing process for the mass production of the oarlock body shown.",
