    id: "eng-2020-hl-q4-a-i", topicId: "eng-1-3", conceptId: "term-allotrope",
    section: "A", questionRef: "2020 HL Q4(a)(i)",
    questionText: "Explain the term allotrope.",
    tariffModel: {"kind":"fixed"}, totalMarks: 4,
    rows: [
    { id: "r-1", kind: "point", verbatim: "The ability of some chemical elements to exist in two or more forms is known as allotropy, e.g. steel can exist in a BBC structure at low temperatures and FCC at 910°C and BCC at 1400°C", marks: 4 },
    ],
