    section: "A", questionRef: "2022 HL Q5(c)(ii)",
    questionText: "Select any two from (i), (ii) or (iii) below and explain: The possible corrosive effects of the environment on metal objects.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 8,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Ferrous metals (e.g. steel) may rust. This may cause early failure of steel products.", marks: null },
    { id: "r-2", kind: "point", verbatim: "An oxide layer can form on some metals such as aluminium giving a dull colour.", marks: null },
    { id: "r-3", kind: "point", verbatim: "Other metals may tarnish due to corrosion e,g. copper can turn a green colour.", marks: null },
    { id: "r-4", kind: "point", verbatim: "The presence of water (especially acidic water) can initiate electrochemical reactions in some metals e.g. stainless steel or zinc are impacted by seawater.", marks: null },
    ],
