    section: "A", questionRef: "2022 HL Q3(b)(ii) — Deferred sitting",
    questionText: "Differentiate between elastic deformation and plastic deformation in metals.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 8,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Elastic deformation is the deformation that disappears upon removal of the external forces causing the alteration and the stress associated with it.", marks: null },
    { id: "r-2", kind: "point", verbatim: "Plastic deformation is a permanent deformation or change in shape of a solid body without fracture under the action of a sustained force.", marks: null },
    ],
