    id: "eng-2024-hl-q7-b-i", topicId: "eng-1-9", conceptId: "suitable-example-where-plastic-product-may",
    section: "A", questionRef: "2024 HL Q7(b)(i)",
    questionText: "Give one suitable example where a plastic product may be upcycled.",
    tariffModel: {"kind":"fixed"}, totalMarks: 6,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Upcycling plastic products generally takes a used low value object and creates a higher value use e.g. Making shoes from recycled PET bottles, shopping bags from recycled bottles, recycled plastic building boards from milk containers, etc.", marks: 6 },
    ],
