    section: "A", questionRef: "2024 HL Q7(b)(ii)",
    questionText: "Explain the glass transition temperature of polymers.",
    tariffModel: {"kind":"fixed"}, totalMarks: 6,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Glass transition temperature describes the temperature at which a solid glassy amorphous polymer changes to a rubbery, viscous polymer. It is engineered by altering the degree of branching or cross-linking in the polymer by the addition of plasticisers.", marks: 6 },
    ],
