    id: "eng-2025-hl-q9-b-ii", topicId: "eng-3-14", conceptId: "benefits-thermostatic-control-home-heating-systems",
    section: "A", questionRef: "2025 HL Q9(b)(ii)",
    questionText: "State two benefits of thermostatic control in home heating systems.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 6,
