    id: "eng-2026-hl-q7-b-ii", topicId: "eng-1-9", conceptId: "distinguish-between-polymer-recycling-polymer-upcycling",
    section: "A", questionRef: "2026 HL Q7(b)(ii)",
    questionText: "Distinguish between polymer recycling and polymer upcycling, and give an example of each.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 6,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Polymer recycling breaks down the plastics into raw materials for use again, these materials are collected, sorted, cleaned and reformed into pellets e.g. plastic bottles can be recycled to be moulded again.", marks: null },
    { id: "r-2", kind: "point", verbatim: "Polymer upcycling transforms plastic objects into products of a higher quality or value e.g. transforming old plastic bags or wrappers into fashion items like wallets, phone cases or tote bags", marks: null },
    ],
