    schemeCitation: "Marking points quoted from the SEC marking scheme, Engineering 2026 Higher Level — © State Examinations Commission.",
    id: "eng-2026-hl-q9-b-i", topicId: "eng-2-15", conceptId: "advantages-toothed-belt-drive-over-chain",
    section: "A", questionRef: "2026 HL Q9(b)(i)",
    questionText: "State two advantages of a toothed belt drive over a chain drive.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 6,
    rows: [
    { id: "r-1", kind: "point", verbatim: "A toothed belt drive operates more quietly and smoothly with less vibration, requires less maintenance and doesn’t need lubrication.", marks: null },
    { id: "r-2", kind: "point", verbatim: "It is lighter in weight, causes less wear on components, provides better power transmission efficiency and resists corrosion since it’s not made of metal.", marks: null },
    ],
